quests[35617] = { id = 35617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiona", objectives = "I have spoken with the rest of my caravan, and we've agreed to rest our wagon for a while while I pledge my service to your garrison.\n\nI think I could be of great use to you. What do you say?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35618] = { id = 35618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin Goldbraids", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35619] = { id = 35619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinchwhistle Gearworks", description = "Commander, a goblin courier arrived this morning.\n\nHe mentioned that he is from a settlement to the southeast called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster.\n\nIf we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide.\n\nI've already spoken to the flight master and he's set up a special flight to get you out there.", completion = "Hey, you're from that Alliance base right?\n\nGlad you made the trip because we really could use your help!", objectives = "Speak to Firn Swiftbreeze to secure a flight to the Pinchwhistle Gearworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35620] = { id = 35620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinchwhistle Gearworks", description = "Commander, a courier arrived this morning.\n\nHe said he's from a goblin settlement to the southeast called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster.\n\nWe're spread thin but if we can earn their trust then we might be able to gain a valuable ally.\n\nHead down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", completion = "Hey, you're from that Horde base right?\n\nGlad you made the trip because we really could use your help!", objectives = "Speak to Hutou Featherwind to secure a flight to the Pinchwhistle Gearworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35621] = { id = 35621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar Sunstrike", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35622] = { id = 35622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 030 - Hidden Stash" }
quests[35623] = { id = 35623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss - Explorer Rixak" }
quests[35624] = { id = 35624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roona", objectives = "I have never seen anyone fight like you, {name}. I am curious about your people and your mission here in this place.\n\nIf I can be of assistance, I would like to join your cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35625] = { id = 35625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shelly Hamby", objectives = "Draenor... even the sound of this place makes me sick.\n\nMy husband is gone. I cannot go home while his memory lingers.\n\nPlease, let me join you and fight for you. Send me to the frontlines, wherever killing is needed.\n\nWith every enemy that I face, perhaps the pain will lessen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35626] = { id = 35626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apprentice Artificer Andren", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35627] = { id = 35627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Basket of Arakkoa Goods" }
quests[35628] = { id = 35628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rangari Chel", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35629] = { id = 35629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindicator Onaala", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35630] = { id = 35630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Visitor: Sappy" }
quests[35631] = { id = 35631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rulkan", objectives = "Prophet Velen spoke highly of you, and I can see that your weapons are keen and your intent is just.\n\nI sense great potential within you. If you will allow it, I would warm my hands by your fire for a while.\n\nI would like to follow you and learn from your people. In return, I shall fight for you.\n\nWhat do you say, traveler?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35632] = { id = 35632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Archaeology", description = "As an archaeologist, it's important to make great discoveries and contributions to the field. Why? Because that's how you make a name for yourself!\n\nEven that hack Harrison Jones has a somewhat reputable name. If he can do it, then you can too!\n\nThe Highmaul are hiding something big in that cave of theirs and we need to get in there and take it!\n\nTake this teleportation beacon and make your way to the back of the cave. Once you find the relic, place the beacon and my team will take care of the rest!", completion = "Great work back there! That's how real archaeology is done!\n\nIt's a good thing you came to me to learn the trade, kid. You've got talent and I'd hate to see it wasted on a putz like Harrison Jones!", objectives = "Recover the Mysterious Artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35633] = { id = 35633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scout Forensics", description = "My entire squad is gone. Some are dead; that much is obvious. The others though... they must be further in.\n\nGo and search the bodies of my squad that you find, each will carry a small pouch of personal items. I would like to return these to their families.\n\nI will go ahead and meet you inside the marsh.", progress = "The families of my squad need closure and we need more information on their deaths.", completion = "Thank you for doing this {name}.  Hopefully they can be cleaned of these foul spores that coat everything here.", objectives = "Collect 5 Rangari Pouches from dead Rangari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35634] = { id = 35634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Control is King", description = "Apexis technology is fascinating, isn't it? Machines powered by solar energy. Energy which itself has been imbued with magic!\n\nSimply brilliant!\n\nAh, but there's always a catch. And I think you may have found it.\n\nBring the interface device back to Veil Terokk, will you? I'll be along shortly with the Apexis cores.\n\nIf my theory is right, we may be able to turn the Adherents' own weapon against them!", progress = "Did you bring the device?", completion = "It will take some time, but this may be the key to our victory.", objectives = "Bring the Apexis Interface to Darkscryer Raastok in Veil Terokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35636] = { id = 35636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Due Respect", description = "A group of Adherents came 'round just before the attack on Skettis. Disguised myself as a mushroom, I did. The fools walked right past me.\n\nMy neighbor up the road was not so lucky.\n\nHe had a fondness for texts, if I recall. Might be valuable information in his hut, if you give Reshad a moment to rummage around.\n\nOh, and bring one of his feathers to the shrine near Veil Terokk, would you? He was such a dear, and I know it's what he'd want.", progress = "Here, I'll take them both for safekeeping.", completion = "<Reshad presses the feather into the tome before sliding it into his robes.>\n\nWe have one more stop before the wayshrine...", objectives = "Retrieve the Feather of Syth and the Saga of Terokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35637] = { id = 35637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Stonefury Cliffs" }
quests[35638] = { id = 35638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Artifact Fragments", progress = "Every little bit counts.", completion = "Every little bit helps." }
quests[35639] = { id = 35639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A TON of Artifact Fragments", progress = "As much as you can carry.", completion = "Great work, {class}! I will let Vindicator Maraad know of your bravery." }
quests[35640] = { id = 35640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for the Fallen", description = "I... almost made it out.  Most of us... dead. The others... they are no longer themselves.\n\nThese lurching spore beasts are the cause, dragging us further into the marsh... stop them.", completion = "Thank you for avenging my fallen friends. We will get to the bottom of this I swear!", objectives = "Kill 7 Fungal Lurchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35641] = { id = 35641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Stonefury Cliffs" }
quests[35642] = { id = 35642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Pod", description = "This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly.\n\nThis is something Khaano would be interested in.", completion = "I've seen these around on corpses and the beasts, but not as big.  Let me see it...", objectives = "Bring the Glowing Red Pod to Khaano at Crimson Fen in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35643] = { id = 35643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 062 - Mountain Climber's Pack" }
quests[35644] = { id = 35644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy for the Living", description = "You can see that the dead were the lucky ones. Those that live wander about attacking anything not infected with these vile spores.\n\nI cannot bring myself to slay them, but if you could bring mercy to those poor people I would be very grateful.", completion = "Perhaps we shouldn't have wasted time on them, this place... drains me. Still it was a good deed you have done.", objectives = "Kill 6 Fungus Covered Shamblers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35645] = { id = 35645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret of the Fungus", description = "I'm beginning to sense a strong... connection... between the fungus and the creatures that inhabit it. There are certain mushrooms that are stronger than others.\n\nI believe if I had some samples of these I could use them, track the source of this foul fungus and... deal with it.", progress = "Where are my mushrooms?!", completion = "Sadly, I'm growing used to the smell of these spores. In fact, they smell quite pleasant now. Perhaps if I eat these it will speed up our work here...", objectives = "Collect 5 Glowing Mushrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35646] = { id = 35646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 006 - Steamwheedle Supplies" }
quests[35647] = { id = 35647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Harvest", description = "The spores grow thick further into the marsh, but those larger fungus beasts are the key.\n\nYes, kill them and take their spore sacs. I will need them to refine my... search.", progress = "Those pods are critical {name}, I need them!", completion = "I... I must consume these like the mushrooms. It will help me locate the source, I swear!", objectives = "Bring Khaano 3 Spore Pods from the Fungal Stompers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35648] = { id = 35648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 005 - Steamwheedle Supplies" }
quests[35649] = { id = 35649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writhing Mire" }
quests[35650] = { id = 35650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter III: Ritual of the Charred", description = "I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark.\n\nI call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger.\n\n- Frenna", completion = "Those ancients are crazy! Hard to believe they'd burn off their own leaves.", objectives = "Kill 4 Ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35651] = { id = 35651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter II: The Harvest", description = "I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them.\n\nPerhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart.\n\nWould killing this botani do us good? I fear I would be no match for it alone.\n\n- Frenna", completion = "Ya took out the big nasty did ya? Yer sure to be causin' some real trouble out there!", objectives = "Kill Ontogen the Harvester.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35652] = { id = 35652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Wood", description = "We got the lumber mill good an' built, but we be needin' more wood!\n\nThe Rangari tol' me there's botani usin' some kinda sap to grow ancients fast as you like.\n\nGet yer hands on some o' that sap and I betcha I can put it work.\n\nWhat? Oh, Glyza here? Found 'er crashed here and she knows a thing or two about lumberjackin'. I'll take her back to the outpost later.\n\nI'll meet ya inside Tangleheart if I can find it.", progress = "Glyza is good with tools.", completion = "Sap? Who called me a sap?! Oh...", objectives = "Collect 100 Ancient Growth Sap from botani or ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35653] = { id = 35653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wood is Wood", description = "Them ancients in Bracken Tangle be crazier than a dwarf who don't like gold.\n\nThe burn their leaves right off their 'eads and make their bark hard to fire.\n\nYa know, that bark might come in 'andy 'round here.\n\nChop down a few ancients and I'll send a lackey to gather their wood.", objectives = "Kill 6 Emberbark Ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35654] = { id = 35654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter I: Plant Food", description = "There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature.\n\nThe botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us.\n\n- Frenna", completion = "Couldn't say what those spores were for, but I feel better knowin' they're gone.", objectives = "Destroy 8 Pollen Pods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35656] = { id = 35656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heartfelt Search", completion = "This is unfortunate... I had hoped... Still we are closer now, we are on the right track to finishing this.\n\nNone too soon either, the screaming beasts are really getting to me...", objectives = "Investigate the strange presence in the Crimson Fen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35659] = { id = 35659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Fen", description = "The pounding in my head is almost unbearable but I must see this through. With all the spore samples I've taken I know where to go and what to do.\n\nI will find the source and spread... no! Destroy it! I will do what needs to be done!", completion = "That is terrible news. I will warn off all scouts from venturing to the Crimson Fen from now on.  Thank you and I am glad you were not affected by the spores...", objectives = "Follow Khaano deeper into the Crimson Fen and deal with what comes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35660] = { id = 35660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 052 - Fungus-Covered Chest" }
quests[35661] = { id = 35661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 054 - Dreamflower" }
quests[35662] = { id = 35662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 053 - Steamwheedle Supplies" }
quests[35663] = { id = 35663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Teamwork", description = "One of the most important skills an archaeology team needs is good teamwork. The key to teamwork is knowing when to give and when to take.\n\nThe Highmaul ogres have been excavating mysterious artifacts from the gorge. I want you to team up with the Highmaul ogres in the name of good archaeology!\n\nRemember what I said about giving and taking? The ogres have given us their hard work to excavate the artifacts. Now I want you to take those artifacts from them and bring them here!\n\nIt's teamwork!", progress = "Have you retrieved the mysterious artifacts? It's all about teamwork!", completion = "You did a great job, kid!\n\nI hope you learned something about teamwork today. Here's your cut, minus my teaching fee... the Steamwheedle Preservation Society service charge... and gratuity of course!", objectives = "Retrieve 10 Mysterious Artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35664] = { id = 35664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seedbearers of Bad News", description = "When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours.\n\nLeaving their remains here would soon cause the outpost to be overrun.\n\nWe have learned that burning their remains prevents this from happening.", progress = "These creatures employ unusual tactics.", completion = "The ancients should not be a problem for your outpost for some time.", objectives = "Burn 5 Ancient Seedbearer corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35665] = { id = 35665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have Company", description = "Commander, I've spotted Iron Horde soldiers nearby.\n\nIt is bold, even for them, to venture into such deadly territory.\n\nIf we do not deal with their presence, they will surely be a threat to your camp.\n\nWhile I scout deeper into the canyons, may I request your help in investigating the camp?", completion = "Thank you, friend. I am in your debt.\n\nThis arrogant Iron Horde has made a dangerous enemy today.", objectives = "Investigate the Iron Horde camp in Sulfur Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35666] = { id = 35666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rangari in the Red", description = "Gorgrond is a very dangerous place and I've sent scouting squads out to investigate various regions.\n\nI've sent one squad to the marsh called the Crimson Fen and they've not come back yet.  I'd like you to find the missing squad and get a report if possible.", completion = "D'kaan sent you? He's not likely to enjoy the report I have to give him.", objectives = "Find Khaano near the Crimson Fen in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35667] = { id = 35667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulltakers in Crimson Fen", description = "Grulkor and his group are often not seen for weeks, returning only when they can carry no more trophies and supplies. He has been gone too long this time.\n\nHe mentioned hunting in the Crimson Fen for the first time, see if he still lives.", completion = "Marrow sent you, eh? Well we leave when I'm done here.", objectives = "Find Grulkor near the Crimson Fen in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35668] = { id = 35668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syth's Secret", description = "Our deceased friend here was hiding more than a love of old scrolls and erotic sorcery-fiction. He had something truly valuable.\n\nIf I'm reading his notes correctly, he claims to have found the Eye of Anzu - Terokk's scrying orb from the days after his fall.\n\nWe need that orb! The notes say he stashed it in a ravager den just up the road.", progress = "To hold such a treasure. I wonder if that Sun-Talon had any idea of the significance?", completion = "<Reshad gazes into the inky orb.>\n\nAmazing. To think Terokk used this very orb to commune with Anzu. One could become quite the darkweaver with an implement such as this.\n\nCome, let's get it safely to the Veil.", objectives = "Retrieve the Eye of Anzu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35669] = { id = 35669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Keeho's Severed Paw", description = "Posted by: Taskmaster Gornek\n\nThe saberon known as Keeho poses a serious threat to Axefall.\n\nHe has taken to slaughtering peons on the night shift and dragging their corpses to his den in the pridelands.\n\nAnyone who can bring me his severed paw as proof of his demise will be rewarded greatly.", progress = "Lok'tar, commander.", completion = "The peons will sing songs of your glory, commander. Lok'tar ogar!", objectives = "Retrieve Keeho's Severed Paw from Keeho the Savage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35670] = { id = 35670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Spineslicer's Husk", description = "Posted by: Killga\n\nI will greatly reward anyone who brings me Spineslicer's husk.\n\nI wish to fashion fine ravager armor, but do not have the skills to take down such a beast.\n\nDon't tear too many holes in it.", progress = "It is an honor to have you in my shop, commander.", completion = "I am glad we can count on you, commander.", objectives = "Retrieve Spineslicer's Husk from Spineslicer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35671] = { id = 35671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering of Shadows", description = "Veil Terokk is just ahead.\n\nLet us hope the others have made the journey safely.", completion = "We owe you a great debt for delivering Reshad safely to us, {name}.\n\nHowever, our struggle has only just begun.", objectives = "Enter Veil Terokk with Reshad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35672] = { id = 35672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Venombarb", description = "Posted by: Hutou Featherwind\n\nVenombarb is feared in the skies above Arak, even by the high arakkoa.\n\nShe has made air travel difficult for our riders, preventing vital supplies from reaching Axefall.\n\nI require no proof of her demise, simply ensure her screech never again echoes among the spires.\n\nShe nests above the howling crag to the northeast.", completion = "A thousand thanks to you, commander. I will call for more supply runs immediately.", objectives = "Kill Venombarb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35673] = { id = 35673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 014 - Appropriated Warsong Supplies" }
quests[35674] = { id = 35674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Keeho's Severed Paw", description = "Posted by: Lieutenant Willem\n\nKeeho, a monstrous saberon, has taken to raiding Southport at night. We're losing men left and right.\n\nI offer a hefty bounty to anyone able to track down Kreeho and bring his severed paw to me.", progress = "Pleasure to see you, sir.", completion = "Well done, commander. For the Alliance!", objectives = "Retrieve Keeho's Severed Paw from Keeho the Savage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35675] = { id = 35675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Spineslicer's Husk", description = "Posted by: Quartermaster Jolie\n\nWe're running out of supplies to repair our troops' armor.\n\nI'll pay handsomely for the husk of the mighty ravager Spineslicer. It would provide us with repair materials for weeks.", progress = "Oh, commander! What an honor!\n\nHow can I help you?", completion = "I didn't think anyone could actually kill the beast. Thank you, commander!", objectives = "Retrieve Spineslicer's Husk from Spineslicer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35676] = { id = 35676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Venombarb", description = "Posted by: Falrogh\n\nVenombarb taunts me every day. Screeching and killing me buzz.\n\nSomebody, anybody, kill the beast. I don't want proof, I want peace and quiet.", completion = "By Muradin'sh beard... you actually killed the beasht. Praishe be to ye, commander ...hic!", objectives = "Kill Venombarb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35677] = { id = 35677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Sunken Fishing Boat" }
quests[35678] = { id = 35678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 015 - Warsong Lockbox" }
quests[35679] = { id = 35679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Fall of Shattrath", description = "Greetings, {name}. I bring another message from Archmage Khadgar.\n\nWe can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day.\n\nThe time has come for us to confront him.\n\nExarch Maladaar should be expecting you at the Spire of Light in Talador. Good luck, {name}.", completion = "I am glad to see you, {name}. Your aid will be invaluable in this critical hour.", objectives = "Speak to Exarch Maladaar at the Spire of Light in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35680] = { id = 35680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Fall of Shattrath", description = "Greetings, {name}. I bring another message from Archmage Khadgar.\n\nWe can no longer ignore Socrethar's presence at Shattrath. He spreads dangerous beliefs, converting more draenei to his \"new order\" with each passing day.\n\nThe time has come for us to confront him.\n\nLady Liadrin should be expecting you at the Spire of Light in Talador. Good luck, {name}.", completion = "I am glad to see you, {name}. Your aid will be invaluable in this critical hour.", objectives = "Speak to Lady Liadrin at the Spire of Light in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35681] = { id = 35681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Supplies", progress = "Every little bit counts.", completion = "A new breastplate, well, a new enough breastplate. I will make sure this is put to good use." }
quests[35682] = { id = 35682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 016 - Warsong Spear" }
quests[35683] = { id = 35683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the City", description = "The Shattrath offensive is going well, but Socrethar refuses to show himself.\n\nDespite our best efforts, we are unable to break into the inner city of Shattrath. The dome's defenses are simply too strong.\n\nHowever, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, and gather their medallions of service.\n\nWhen we show him proof of their demise, his pride will surely force him to face us.", progress = "What I ask is no easy task, for his scions are formidable. How goes the offensive?", completion = "Excellent. These insignias will surely bring Socrethar out of hiding.", objectives = "Collect 100 Sargerei Insignias.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35684] = { id = 35684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the City", description = "The Shattrath offensive is going well, but Socrethar refuses to show himself.\n\nAnd despite our best efforts, we are unable to break into the inner city, where he resides.\n\nHowever, we think we can lure Socrethar out of hiding. Defeat his lieutenants and warriors, then gather their medallions of service.\n\nWhen we show him proof of their demise, his pride will surely force him to face us.", progress = "What I ask is no easy task, for his followers are formidable. How goes the offensive?", completion = "Excellent. These insignias will surely bring Socrethar out of hiding.", objectives = "Collect 100 Sargerei Insignias.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35685] = { id = 35685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socrethar's Demise", description = "Meet me down by the entrance to the Shattrath dome.\n\nThere, we will issue our challenge to the Sargerei leader. If he accepts our challenge, it is there that he shall meet his end.\n\nThe creature that calls himself Socrethar was once my brethren. I can only hope that there is still some Light left within him.", completion = "Finally, it is done. Othaar... my old friend... be at peace now.", objectives = "Kill Socrethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35686] = { id = 35686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage and Wisdom", description = "An endless war wages between the creatures of the eastern wilds and the beasts of the western wasteland.\n\nShould one side overwhelm the other, all of Draenor would fall at the hand of the victor.\n\nI sent Rangari Erdanii to the heart of the battle between these two forces. It is likely that she will need your help, commander.", completion = "These creatures are relentless in their assault against one another.", objectives = "Speak to Rangari Erdanii at Affliction Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35687] = { id = 35687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socrethar's Demise", description = "Meet me down by the entrance to the Shattrath dome.\n\nThere, we shall issue our challenge to the Sargerei leader. If he accepts, it is there that he shall meet his end.\n\nI must admit, {name}, I am looking forward to this.", progress = "What is it?", completion = "Finally, it is done. This creature of darkness shall torment us no longer. Shattrath is free of his taint.", objectives = "Kill Socrethar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35688] = { id = 35688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Enavra Varandi" }
quests[35689] = { id = 35689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Artifact Fragments", progress = "Every little bit counts.", completion = "Every little bit helps." }
quests[35690] = { id = 35690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bunch of Artifact Fragments", progress = "The more, the better!", completion = "That must of taken great effort to get back to us. You deserve this reward, friend." }
quests[35691] = { id = 35691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A TON of Artifact Fragments", progress = "As much as you can carry.", completion = "Great work, {class}! I will let Vindicator Maraad know of your bravery." }
quests[35692] = { id = 35692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 010 - Freshwater Clam" }
quests[35693] = { id = 35693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Harsh Reminder", description = "Welcome to the front lines, commander, where the wastelands and the jungle collide.\n\nThe battle below rages on, but I believe one side is beginning to overwhelm the other. This cannot be allowed to happen.\n\nThe gronnlings are gaining an upper hand and must be stopped before they pose a threat to Highpass.\n\nI will get closer to the battle while you thin their ranks. Meet me within Affliction Ridge when you are done.", completion = "You have a true talent for combat.", objectives = "Kill 8 denizens of the wasteland in Affliction Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35694] = { id = 35694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 011 - Golden Kaliri Egg - TSH" }
quests[35695] = { id = 35695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 022 - Warsong Cache" }
quests[35696] = { id = 35696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 048 - Burning Blade Cache" }
quests[35697] = { id = 35697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace Offering", description = "We need allies amongst these spires, and quickly. Commander, I believe it would be wise if you sought out aid.\n\nThere is a lone arakkoa outcast southeast of here living near a ravager nest. The ravagers do not attack him - I suspect he has information on the beasts we may be able to use.\n\nI have our last crate of cactus apple surprise ready for you. It is our best shot, <sir/madame>.", progress = "Any luck, commander?", completion = "I believe we can come to an arrangement, savior of Skettis. But first...", objectives = "Deliver the Crate of Cactus Apple Surprise to Dusk-Seer Irizzar in the Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35699] = { id = 35699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace Offering", description = "We could really use an ally to trade with, commander.\n\nThere's an arakkoa outcast living in the middle of a ravager nest northeast of here... do you think he might ally with us? He must have some sort of secret to keeping those ravagers at bay.\n\nI have one last crate of my Northshire Port. Maybe that will help convince him that we're friendly.", progress = "Welcome back! How did things go with the arakkoa?", completion = "I believe we can come to an arrangement, savior of Skettis. But first...", objectives = "Deliver the Crate of Northshire Port to Dusk-Seer Irizzar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35701] = { id = 35701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 1" }
quests[35702] = { id = 35702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chains of Iron", description = "The artifact we seek is within our grasp.\n\nBe prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated.\n\nI will join you in this battle as soon as you arrive.", progress = "We have the artifact, and with it we will make the Iron Horde pay.", completion = "Yes... Think of the orcs that will fall before us with this power...", objectives = "Defeat Captain Brak and find the Heart of the Magnaron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35703] = { id = 35703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure Barrier 1" }
quests[35704] = { id = 35704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When All Is Aligned", description = "The ravenspeaker acolytes have been equipped with Apexis interfaces, they just need to get close enough.\n\nCome, let us take to the skies and secure the Terrace of Dawn.\n\nWhen all is aligned, we shall turn the false suns against one another and the spires shall burn like torches!\n\nI look forward to penning your actions into history.", completion = "Percy and I want to give you something as a token of our thanks. It's not much but please, take your reward.", objectives = "Fly upon Ka'alu and kill 80 Adherents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35705] = { id = 35705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Deals Anywhere", description = "Commander, two goblin smugglers - Mixxy and Trixxy Weldblast - came through here recently and went off towards the bog to the east.\n\nThey had drilling equipment but weren't carrying any weapons, <sir/madame>.\n\nI'd bet anything that they'll have materials we'd want, and that they could use some protection in return.\n\nCommander, I think seeking them out would be a good idea.", completion = "I don't know what you're doin' all the way out here, but mind helpin' a gal out since you're stopping by?", objectives = "Speak to Mixxy Weldblast in Murkbog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35706] = { id = 35706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sticky Situation", description = "We were hauling batteries to the excavation site and I crashed my freakin' car!\n\nMy sister didn't even look back. I took the turn a little fast, so what? It happens!\n\nPoint is, the batteries went flying everywhere and I'm in no condition to lift them out.\n\nSo what do you say? Wanna help me out?", progress = "Do you have the batteries?", completion = "You're a real doll. Let's get out of here.", objectives = "Retrieve 5 Submerged Batteries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35707] = { id = 35707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tangleheart", description = "Hey there, peach. We've got the lumber mill good and ready, but we gotta find a way of choppin' wood fast out here.\n\nThe Laughing Skull talked about Tangleheart, where the botani grow things quick as a quark.\n\nI'm headin' there now.", completion = "Hey! Looky what I found here.", objectives = "Speak to Penny Clobberbottom outside Tangleheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35708] = { id = 35708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tangleheart", description = "The Rangari have been here for a tick, and they hear tell from the Laughing Skull o' a place called Tangleheart.\n\nSeems some really bad ancients come from there, and botani use a kind o' sap to grow them quickly.\n\nI think we could use that for yer outpost. Hey, wood is wood, right?\n\nI'll meet ya there.", completion = "Cheers! I found a goblin skulkin' about here. Think I'll keep 'er around. Says she knows things about lumberjackin'.", objectives = "Speak to Glirin outside Tangleheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35709] = { id = 35709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Laughing Skull Cache I" }
quests[35711] = { id = 35711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 059 - Abu'gar's Tenacity" }
quests[35712] = { id = 35712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 012 - Redclaw the Feral" }
quests[35713] = { id = 35713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tinkertoss Twins", description = "Commander, two gnomish smugglers passed by while you were out - Filbert and Dilbert Tinkertoss. They were headed towards the bog to the east.\n\nThey had all sorts of drilling equipment but didn't seem to have any weapons.\n\nWhat do you think of offering them protection in exchange for some of their materials?\n\nI'll jot down where they were headed in case you decide to go.", completion = "You're armed to the teeth! Say, would you be interested in helping a weary gnome out?", objectives = "Speak to Filbert Tinkertoss in Murkbog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35714] = { id = 35714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 001 - Greatfeather" }
quests[35715] = { id = 35715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 002 - Gar'lua the Wolfmother" }
quests[35716] = { id = 35716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sticky Situation", description = "A squadron of arakkoa spotted us while we were en route to the excavation site and took out our caravan. My brother made it to safety in the chaos.\n\nLucky son of a tinker.\n\nI can't leave without the batteries for our drill, but they all fell into the bog and I can't even get them to budge.\n\nAny chance you could retrieve them for me?", progress = "Any luck?", completion = "You're a lifesaver! Let's get these to the excavation site.", objectives = "Retrieve 5 Submerged Batteries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35717] = { id = 35717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 015 - Gnarlhoof the Rabid" }
quests[35718] = { id = 35718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back on Track", description = "You're a lifesaver, I'll tell you what.\n\nSay, how about you go on ahead to the excavation site and let my sister know I'm on my way. I'll get everything neat and tidy and go get a new cart to lug these over.", completion = "Oh, Mixxy sent you? What a relief. I'm not even armed!", objectives = "Speak to Trixxy Weldblast in Veil Zekk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35719] = { id = 35719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back on Track", description = "Now that the batteries are out of the bog I can radio in some more copters to take them to camp.\n\nI'll stay here until they arrive, but you should go ahead to my brother Dilbert and let him know what happened. He must be worried sick!", completion = "Oh, thank goodness. I don't even have any weapons!", objectives = "Speak to Dilbert Tinkertoss in Veil Zekk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35720] = { id = 35720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seamless Breastplate" }
quests[35722] = { id = 35722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Soled Treads", progress = "Every little bit counts.", completion = "A new set of footwear is always welcome. You ever march across Azeroth? No? Well, if you do, take multiple pairs of shoes, unless you're a troll I guess. I will make sure these are put to good use." }
quests[35723] = { id = 35723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two-Toned Greaves", progress = "Every little bit counts.", completion = "Many neglect protecting their lower legs. Just ask One-Legged Tom. I will make sure these are put to good use." }
quests[35724] = { id = 35724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood-Washed Greaves" }
quests[35725] = { id = 35725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Faebright" }
quests[35726] = { id = 35726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balanced Short Sword", progress = "Every little bit counts.", completion = "A short sword, we can always use new blades. It's too bad it isn't longer, but they can't all be long swords.  I will make sure it's put to good use." }
quests[35727] = { id = 35727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slightly-Bent Short Sword", progress = "Every little bit counts.", completion = "A short sword, we can always use new blades. I will make sure it's put to good use." }
quests[35728] = { id = 35728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decent Barrier Shield", progress = "Every little bit counts.", completion = "Many around here could use a good shield. It's never good to get too close with the enemy.  I will make sure this is put to good use." }
quests[35729] = { id = 35729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frosty Bulwark", progress = "Every little bit counts.", completion = "Many around here could use a good shield. It's never good to get too close with the enemy.  I will make sure this is put to good use." }
quests[35730] = { id = 35730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cauterizing Wounds", description = "You have saved my most precious companion, Nisha. I owe you a great debt.\n\nThe Iron Horde lured me away to separate us. I shall not make the same mistake again.\n\nThey have inflicted grievous wounds, and I fear we must cause her even more pain before the healing process can begin.\n\nPlease use a burning log from the nearby fire to cauterize her wounds.\n\nI will hold her down.", progress = "Nisha must make it through this.", completion = "Thank you. Her wounds have closed.", objectives = "Use a Burning Log to cauterize Nisha's wounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35731] = { id = 35731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Ba'ruun" }
quests[35732] = { id = 35732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shinri" }
quests[35733] = { id = 35733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Talonpriests", description = "That gavel was once known as Beakbreaker. In his final, darkest days, Terokk used it to perform grim, damnable acts of sacrifice. \n\nIt is best not to dwell on those days.\n\nTerokk was sealed away deep within the shadows to rest, and perhaps to heal.\n\nMaking contact with him will take a great deal of effort, so in the meantime, allow me to tell you of his more glorious exploits. Before this wretched curse took hold.\n\nPlease, place the gavel upon the effigy.", completion = "<As you place the gavel at the base of the effigy, Reshad speaks over your shoulder.>", objectives = "Place Terokk's Gavel on the Effigy of Terokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35734] = { id = 35734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Talon King", description = "<As Reshad begins reciting a tale of Terokk's glory days, your eyes fall to the twin swords at the effigy's belt.\n\nThey had seemed so plain in Skettis, but now they thrum with power, as if reacting to the scrollkeeper's words.>", completion = "That was but one of many such tales.\n\nNo arakkoa living or dead has ever compared to the Talon King.", objectives = "Use the Effigy of Terokk to re-live Terokk's battle with the Bloodmane. Slay 30 Bloodmane Shortfangs, 20 Mature Bloodmane saberon, and Pridelord Karash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35735] = { id = 35735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 021 - Berserk Shredder" }
quests[35736] = { id = 35736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writing in the Snow", description = "This is a worn page from Shadow Hunter Bwu'ja's journal. It appears to be a sketch of the entrance of the Bloodmaul Slave Mines. Rokhan, in your garrison, would be very interested in this.", completion = "Excellent work. Your service is always appreciated, {name}.", objectives = "Deliver the tattered journal page to Rokhan in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35737] = { id = 35737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writing in the Snow", description = "This is a worn page from Owynn Graddock's journal. It appears to be a sketch of the entrance of the Bloodmaul Slave Mines. Bodrick Grey, in your garrison, would be very interested in this.", completion = "Excellent work. Your service is always appreciated, {name}.", objectives = "Deliver the tattered journal page to Bodrick Grey in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35738] = { id = 35738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Natural", description = "So you have a smuggler's den, huh?\n\nI'd love to trade with ya, toots, I really would, but my laser cannon isn't even functional right now.\n\nI'll tell you what. See all the ancients around here? They got toasted good by the arakkoa's weapon, and they're practically walking piles of charcoal.\n\nBring me some charcoal to power this thing and you've got a deal.", progress = "If you've got the stuff, let's talk.", completion = "That ought to do it! Nice work.", objectives = "Collect 30 Fresh Charcoal from ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35739] = { id = 35739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Natural", description = "Oh, you have a trading post?\n\nFantastic!\n\nLet's make a deal. You help me power up my laser cannon, and I'll trade some of this... thermo... ultra... obsidiglass with you for some weapons.\n\nThe ancients all around here are practically made of charcoal after the arakkoa weapon hit, you should go get some of that!", progress = "Blasted refurbished goblin tech is always malfunctioning.", completion = "That's... quite a bit of charcoal. Nicely done!", objectives = "Collect 30 Fresh Charcoal from ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35740] = { id = 35740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frightening Voodoo Doll", progress = "Every little bit counts.", completion = "Voodoo dolls are highly prized by many soldiers. I will see that this one makes it into their hands." }
quests[35741] = { id = 35741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sad Voodoo Doll", progress = "Every little bit counts.", completion = "Voodoo dolls are highly prized by many soldiers. I will see that this one makes it into their hands." }
quests[35742] = { id = 35742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attuned Alchemist Stone", progress = "Every little bit counts.", completion = "It's good to see that the alchemist stone has been restored. I will make sure that it is delivered to your master alchemist. He was looking for a new stone for his apprentice." }
quests[35743] = { id = 35743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lesser Alchemist Stone", progress = "Every little bit counts.", completion = "It's good to see that the alchemist stone has been restored. I will make sure that it is delivered to your master alchemist. He was looking for a new stone for his apprentice." }
quests[35744] = { id = 35744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending Executions", description = "We arrived as soon as we could... but we be too late. Da Iron Horde has taken our warriors prisoner.\n\nNo doubt they be trying ta squeeze info out of da troops.\n\nI fear once they are done with da interrogation they gonna execute their prisoners. Time be running out.", completion = "Da prisoners be shaken up, but they are free. We be in your debt, {name}.", objectives = "Kill 3 Ironmarch Executioners", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35745] = { id = 35745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack of the Iron Horde", description = "We received reports of the Dark Portal turning red right before the attack. They call themselves the Iron Horde.\n\nTheir army is extremely well equipped, and their numbers appear to be unending.\n\nThey have already taken Okril'lon Hold and Nethergarde Keep. Our troops on the frontlines could use your help, {class}.", completion = "Aka'Magosh, champion. I'm sure your presence on the field was inspiring for the troops.", objectives = "Kill 8 Ironmarch Grunts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35746] = { id = 35746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Siege", description = "Those Iron Horde cannons are laying waste to our troops. I'm not sure how much more of this we can handle. Our forces are already spread too thin.\n\nThere has to be a way to stop those war machines.", completion = "It will take the Iron Horde quite a while to get those demolishers operational again. Throm-Ka, {name}.", objectives = "Sabotage 3 Iron Demolishers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35747] = { id = 35747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking a Trip to the Top of the Tank", description = "We cannot risk the reactivation of the Dark Portal. Now is the time for the deathblow.\n\nThaelin should have figured out how to get that tank working by now. Take him with you, and turn that tank against the Dark Portal itself. We will follow behind you.", completion = "This... I can work with this.", objectives = "Speak with Thaelin Darkanvil, then escort him to the top of the Iron Worldbreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35748] = { id = 35748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subversive Scouts", description = "We have been unable to execute a vast majority of our battleplans. We are definitely being watched.\n\nThe Iron Horde must have scouts planted throughout the Blasted Lands. Victory is slipping away from us.", completion = "You killed how many scouts? No wonder we have been unable to execute our plans...", objectives = "Kill 5 Iron Horde scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35749] = { id = 35749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passable Old Staff", progress = "Every little bit counts.", completion = "Ah a staff, the staple mage weapon. If only more would use them, they provide such better protection than carrying around a book, or lamp. I will see if I can make sure a few more staves are handed out first." }
quests[35750] = { id = 35750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunatic Lieutenants", description = "It is time we learned more about our new enemy.\n\nOur scouts have identified a number of the Iron Horde's lieutenants. Their attack is too organized to be run by tribal knowledge alone. Surely their lieutenants have access to secret battleplans. \n\nYou are the only soldier I can trust with this mission, {name}.", progress = "Were you able to gain access to any battleplans?", completion = "Let's take a look at these battleplans.", objectives = "Collect Iron Horde battleplans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35751] = { id = 35751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Nethergarde", description = "The Iron Horde controls Nethergarde Keep, but they are fools if they think we will let them retain such a strategic position.\n\nMy best troops are more than eager to spill the blood of those savages, but we need a champion like yourself to lead the charge.", completion = "The Iron Horde will learn to fear us, as they should.", objectives = "Plant the Horde flags inside Nethergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35752] = { id = 35752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magically Banded Totem", progress = "Every little bit counts.", completion = "Totems are fierce weapons. At times I wish they could be wielded by all, but in the hands of our larger soldiers they are devastating." }
quests[35753] = { id = 35753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanded Totem", progress = "Every little bit counts.", completion = "Totems are fierce weapons. At times I wish they could be wielded by all, but in the hands of our larger soldiers they are devastating." }
quests[35754] = { id = 35754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leering Ritual Mask", progress = "Every little bit counts.", completion = "Ooh a ritual mask. Many of our warriors are used to wearing masks into battle, I am sure one would find this beneficial." }
quests[35755] = { id = 35755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intricately Carved Battle Staff", progress = "Every little bit counts.", completion = "Ah a staff, the staple mage weapon. If only more would use them, they provide such better protection than carrying around a book, or lamp. I will see if I can make sure a few more staves are handed out first." }
quests[35756] = { id = 35756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing Ritual Mask" }
quests[35757] = { id = 35757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extendable Wand" }
quests[35758] = { id = 35758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patched Wand", progress = "Every little bit counts.", completion = "Perfect, we needed more wands. You would be surprised how rare wands are these days, one would think they have gone out of style." }
quests[35759] = { id = 35759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 065 - Abandoned Cargo" }
quests[35760] = { id = 35760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toothsmash the Annihilator", description = "If the battleplans you brought back are true, the Dreadmaul ogres are as much to blame for this devastation as the Iron Horde. It's time we send those ogres a message.\n\nIt looks like the Iron Horde's main contact is a large ogre in Dreadmaul named Toothsmash. Killing him will put a dent in their battleplans.", completion = "Toothsmash is dead? Good, I'm sure it will take the Iron Horde a while to find another ogre smart enough to help them with their efforts.", objectives = "Kill Toothsmash the Annihilator", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35761] = { id = 35761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ransacking Nethergarde", description = "After the Iron Horde took Nethergarde we attacked. While we killed the Iron Horde at Nethergarde they brought more forces through the portal and took Okril'lon Hold. So many souls stripped of their bodies by those savages.\n\nWe must not forget those that gave their lives at Nethergarde. If you find any mementos of the fallen, bring them back to me.", progress = "Did you find anything?", completion = "Throm-Ka, {name}. These mementos will forever remind us of our champions.", objectives = "Collect Master Aitokk's Axe, Neka's Poison Flask, and Overseer Struk's Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35762] = { id = 35762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Dreadmaul", description = "The stupidity of the Dreadmaul ogres never ceases to amaze me. The Iron Horde is clearly using them to further their own nefarious agenda.\n\nRegardless, we must show the ogres what happens when you confront the true Horde. I think it's time we send the Dreadmaul ogres a message.", completion = "It's important that our enemies understand what happens when you attack the true Horde. I'm glad you could be there to show them.", objectives = "Kill 8 Dreadmaul Ogres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35763] = { id = 35763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'mak Bladetwist", description = "With the intelligence you have gathered we have learned this assault is being led by a powerful Iron Horde orc named Gar'mak Bladetwist. He is hunkered down inside Okril'lon Hold.\n\nKilling him will not win this war, but it will surely break down the Iron Horde's communication. This will buy us valuable time while we gather more forces and outline a battleplan to deal with this new threat.", completion = "It was an honor fighting alongside of you, {name}.", objectives = "Kill Gar'mak Bladetwist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35764] = { id = 35764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrilla's Revenge", description = "The Dreadmaul ogres think they have bested us? They will all suffer. Here take this poison, place a couple drops in their rat stew.\n\nThe poison will slowly eat away at their insides. Causing a prolonged and painful death, just like they deserve.", completion = "I wish I could be there to watch their faces as they suffer. I hope they all die a slow horrible death.", objectives = "Poison the Dreadmaul ogre food supply.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35765] = { id = 35765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 049 - Adventurer's Pack" }
quests[35766] = { id = 35766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I See Dead Arakkoa", description = "I've got a strange problem and I'm hoping you might be able to help. I don't know who else could help, to be honest.\n\nMy workers keep saying they're seeing the ghost of the arakkoa that used to head up this place.\n\nI know, I know, it's crazy but could you take my Ghostogrifier 12000 to her body and check?\n\nIf there's a ghost around here, it'll find it. If there's not, then my workers are trying to slack off on the clock.", completion = "Well, I'll be. Ghosts. Who knew?", objectives = "Use the Ghostogrifier 12000 and kill the spirit of Talonpriest Zekk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35767] = { id = 35767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimental Healing Potion", progress = "Every little bit counts.", completion = "The troops can always use the extra healing potions in the field. I'll distribute them out immediately!" }
quests[35768] = { id = 35768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ultra Healing Potion", progress = "Every little bit counts.", completion = "The troops can always use the extra healing potions in the field. I'll distribute them out immediately!" }
quests[35769] = { id = 35769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowered Scroll" }
quests[35770] = { id = 35770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemist Notebook", progress = "Every little bit counts.", completion = "I see you found the missing alchemy apprentice's field guide. I'm sure they will be happy to see that all of the sections were restored. I will return it to their master for safe keeping." }
quests[35771] = { id = 35771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legible Scroll", progress = "Every little bit counts.", completion = "A good buff scroll can mean everything in the thick of battle. I will make sure that this is available to our troops." }
quests[35772] = { id = 35772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemist Field Guide", progress = "Every little bit counts.", completion = "I see you found the missing alchemy apprentice's field guide. I'm sure they will be happy to see that all of the sections were restored. I will return this to their master for safe keeping." }
quests[35773] = { id = 35773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strangely Pleasant Painting" }
quests[35774] = { id = 35774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Mostly Stable\" Elixir", progress = "Every little bit counts.", completion = "I'm glad you were able to stabilize this dangerous elixir. We weren't sure what else we would have done with it if it was still as volatile as before. We'll keep this on hand if our troops need an extra boost in strength." }
quests[35775] = { id = 35775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moldy Book", progress = "Every little bit counts.", completion = "Ooh, a mysterious tome. These contain valuable secrets that could aid a soldier in battle." }
quests[35776] = { id = 35776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overly Clear Book" }
