quests[35778] = { id = 35778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 020 - Ancient Blademaster - TSH" }
quests[35779] = { id = 35779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bent Card", progress = "Every little bit counts.", completion = "Most would scoff at a card, but they underestimate the risk of idle soldiers. Some cards are so beloved and tended by soldiers that their decks are imbued with special powers and handed down." }
quests[35780] = { id = 35780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Stable\" Elixir" }
quests[35781] = { id = 35781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restored Infantry Cloak", progress = "Every little bit counts.", completion = "We can always use extra cloaks. Who knows how cold the nights can be in this land." }
quests[35782] = { id = 35782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I See Dead Arakkoa", description = "Say, while you're here would you mind helping me out with a major problem?\n\nThe workers keep saying that they're seeing the ghost of the head arakkoa that used to be here.\n\nI don't believe it for a second but could you take my Ghostogrifier 12000 to her body and check?\n\nIf they're not crazy, it'll prove it.", completion = "You're kidding! What a world.", objectives = "Use the Ghostogrifier 12000 and kill the spirit of Talonpriest Zekk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35783] = { id = 35783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenic Survivalist Cloak", progress = "Every little bit counts.", completion = "We can always use extra cloaks. Who knows how cold the nights can be in this land." }
quests[35784] = { id = 35784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette Boss" }
quests[35785] = { id = 35785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstract Painting", progress = "Every little bit counts.", completion = "A painting? We don't get many of these, but I think this could be just the thing to distract or cheer up the garrison soldier. I know just the place to put it." }
quests[35786] = { id = 35786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronze Victory", progress = "We're deep in enemy territory, staking our claim. Eventually, the locals will come sniffing around.\n\nWe can't show them weakness. Any attack on us must be met fast and furious.", completion = "With every victory, or claim here grows more strong." }
quests[35787] = { id = 35787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Victory", progress = "A victory is a twin-edged axe. It stakes a claim, but it also foments rebellion and revenge. We must be complete and decisive.", completion = "Without each battle, or sovereignty here grows, Commander." }
quests[35788] = { id = 35788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold Victory", progress = "The stronger our enemies, the more soundly we must beat them. With so much at stake, we must strive for total victory.", completion = "Our foes cringe, Commander. Hah! They'll lick their wounds for days before even dreaming of another fight." }
quests[35789] = { id = 35789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infantry Leather Cap", progress = "Every little bit counts.", completion = "The recruits always leave their helms behind and we have a tough time keeping up with the replacement requests. We will return the cap to the stockpile." }
quests[35790] = { id = 35790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Duty Utilicap", progress = "Every little bit counts.", completion = "The recruits always leave their caps and helmets behind and we have a tough time keeping up with the replacement requests. We will return the cap to the stockpile." }
quests[35791] = { id = 35791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absorbable Vellum" }
quests[35792] = { id = 35792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stitched Saddle Bag", progress = "Every little bit counts.", completion = "You can never have too many saddle bags. With exploration parties going further into the wilderness, they will need to take more supplies. I will deliver this to the next exploration unit." }
quests[35793] = { id = 35793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transferable Vellum" }
quests[35794] = { id = 35794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huntsman's Saddlebag", progress = "Every little bit counts.", completion = "You can never have too many saddle bags. With exploration parties going further into the wilderness, they will need to take more supplies. I will deliver this to the next exploration unit." }
quests[35795] = { id = 35795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marching Drum", progress = "Every little bit counts.", completion = "The officers have been asking for more equipment to help inspire their men to follow commands. Now we can deliver on their request." }
quests[35796] = { id = 35796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzy War Drum" }
quests[35797] = { id = 35797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ebon Hunter", description = "The laser should be good to go once we get it set up, there's just one more thing I need.\n\nThere's a spore walker that hunts on the delta just southeast from here. It has an apparatus on its face that can fire a powerful laser - way more powerful than what we have hooked up.\n\nI want it.\n\nWe'll be mining faster than you can imagine once we get that bad boy hooked up!", progress = "I should probably have mentioned that the laser is pretty... potent.", completion = "Perfection. Let's get it hooked up!", objectives = "Collect an Organic Laser Apparatus from the Ebon Hunter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35798] = { id = 35798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Glowing Cave Blossom" }
quests[35799] = { id = 35799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wooly Bedroll", progress = "Every little bit counts.", completion = "With our limited supplies, repairing and repurposing everything is a must. Now we have some extra necessities for our field kits." }
quests[35800] = { id = 35800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luxurious Bedroll", progress = "Every little bit counts.", completion = "With our limited supplies, repairing and repurposing everything is a must. Now we have some extra necessities for our field kits." }
quests[35801] = { id = 35801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restored Lace Kerchief", progress = "Every little bit counts.", completion = "I recognize this kerchief, but it appears that you have repaired it. I know someone will be very happy to see this again." }
quests[35802] = { id = 35802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immaculate Lace Kerchief" }
quests[35803] = { id = 35803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lesser Mage Robe", progress = "Every little bit counts.", completion = "This robe will be perfect for one of the apprentice mages. Thank you for keeping our armaments well supplied." }
quests[35804] = { id = 35804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Mage Robe" }
quests[35805] = { id = 35805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Duty Knapsack", progress = "Every little bit counts.", completion = "Adventurers and scouts go through knapsacks and other bags quickly. Having a few extra on hand will help us keep up with the demand." }
