quests[35807] = { id = 35807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Erosian", description = "Defeating Erosian has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", completion = "One minute you are skirting the cauldrons avoiding the Gronn, the next a blast a steam followed by burning hot claws.  Erosian's death should make our scouts lives a lot easier!", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35808] = { id = 35808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Erosian", description = "Defeating Erosian has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", completion = "One minute you are skirting the cauldrons avoiding the Gronn, the next a blast a steam followed by burning hot claws.  Erosian's death should make our scouts lives a lot easier!", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35809] = { id = 35809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Dessicus", description = "Defeating Dessicus has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", completion = "You have defeated yet another deadly beast in Gorgrond.\n\nDessicus cared little on who he preyed upon, they all went into his salt pools forever. You have saved many lives {name}!", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
