quests[35811] = { id = 35811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Crater Lord Igneous", description = "Defeating Crater Lord Igneous has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", completion = "I thought I felt less quakes in the earth. His fury caused untold damage to this world, it is good that he has fallen to you.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35812] = { id = 35812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Crater Lord Igneous", description = "Defeating Crater Lord Igneous has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", completion = "I thought I felt less quakes in the earth. His fury caused untold damage to this world, it is good that he has fallen to you.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35813] = { id = 35813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Fungal Praetorian", description = "Defeating the Fungal Praetorian has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", completion = "I've heard tales of the Crimson Fen from the rangari; no one has yet returned from there. If this was the reason then we can all breathe safer now.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35814] = { id = 35814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Fungal Praetorian", description = "Defeating the Fungal Praetorian has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", completion = "I've heard tales of the Crimson Fen from the Laughing Skull and how no one ever returns from there. If this is part of the reason, then we can all breathe safer now.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35815] = { id = 35815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Charl Doomwing", description = "Defeating Charl has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", completion = "Our purpose here was hard enough without a giant beast like Charl harassing our scouts and aggravating the Gronn.\n\nGlory to you {name}!", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35816] = { id = 35816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Charl Doomwing", description = "Defeating Charl has yielded you a trophy worthy of acclaim.\n\nTake this to Maraad at Highpass.", completion = "Our purpose here was hard enough without a giant beast like Charl harassing our scouts and aggravating the Gronn.\n\nYou have saved the rangari a great deal of punishment with this kill, {name}!", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
